import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { useAppContext } from "../context/AppContext";

export function useThreeJS(containerRef) {
  const { state } = useAppContext();
  const sceneRef = useRef(null);
  const rendererRef = useRef(null);
  const cameraRef = useRef(null);
  const earthRef = useRef(null);
  const animationIdRef = useRef(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // Initialize Three.js scene
  useEffect(() => {
    if (!containerRef.current || isInitialized) return;

    // Scene setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x000000);
    sceneRef.current = scene;

    // Camera setup
    const camera = new THREE.PerspectiveCamera(
      75,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.set(
      state.camera.position.x,
      state.camera.position.y,
      state.camera.position.z
    );
    cameraRef.current = camera;

    // Renderer setup
    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: true,
    });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setClearColor(0x000000, 1);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    rendererRef.current = renderer;

    // Add renderer to DOM
    containerRef.current.appendChild(renderer.domElement);

    // Lighting setup
    const ambientLight = new THREE.AmbientLight(0x404040, 0.4);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
    directionalLight.position.set(5, 3, 5);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 2048;
    directionalLight.shadow.mapSize.height = 2048;
    scene.add(directionalLight);

    // Create Earth geometry
    const earthGeometry = new THREE.SphereGeometry(1, 64, 64);

    // Load textures
    // const textureLoader = new THREE.TextureLoader(); // Temporarily commented out
    // const earthTexture = textureLoader.load("/Albedo.jpg"); // Temporarily commented out
    // const bumpTexture = textureLoader.load("/Bump.jpg"); // Temporarily commented out
    // const nightTexture = textureLoader.load("/night_lights_modified.png"); // Temporarily commented out
    // const cloudTexture = textureLoader.load("/Clouds.png"); // Temporarily commented out

    // Earth material (TEMPORARILY SIMPLIFIED)
    const earthMaterial = new THREE.MeshBasicMaterial({ color: 0x00ff00 }); // Bright green

    // Original Earth material (commented out for testing)
    // const earthMaterial = new THREE.MeshPhongMaterial({
    //   map: earthTexture,
    //   bumpMap: bumpTexture,
    //   bumpScale: 0.05,
    //   transparent: true,
    // });

    // Create Earth mesh
    const earth = new THREE.Mesh(earthGeometry, earthMaterial);
    // earth.receiveShadow = true; // Not needed for MeshBasicMaterial
    // earth.castShadow = true; // Not needed for MeshBasicMaterial
    scene.add(earth);
    earthRef.current = earth;

    // Handle window resize
    const handleResize = () => {
      if (cameraRef.current && rendererRef.current) {
        cameraRef.current.aspect = window.innerWidth / window.innerHeight;
        cameraRef.current.updateProjectionMatrix();
        rendererRef.current.setSize(window.innerWidth, window.innerHeight);
      }
    };

    window.addEventListener("resize", handleResize);
    setIsInitialized(true);

    // Cleanup function
    return () => {
      window.removeEventListener("resize", handleResize);
      if (animationIdRef.current) {
        cancelAnimationFrame(animationIdRef.current);
      }
      if (containerRef.current && rendererRef.current) {
        containerRef.current.removeChild(rendererRef.current.domElement);
      }
      if (rendererRef.current) {
        rendererRef.current.dispose();
      }
    };
  }, [containerRef, isInitialized]);

  // Animation loop
  useEffect(() => {
    if (!isInitialized || !state.animation.isPlaying) return;

    const animate = () => {
      if (earthRef.current && state.camera.autoRotate) {
        earthRef.current.rotation.y += state.camera.rotationSpeed;
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }

      animationIdRef.current = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      if (animationIdRef.current) {
        cancelAnimationFrame(animationIdRef.current);
      }
    };
  }, [
    isInitialized,
    state.animation.isPlaying,
    state.camera.autoRotate,
    state.camera.rotationSpeed,
  ]);

  // Update camera position when state changes
  useEffect(() => {
    if (cameraRef.current) {
      cameraRef.current.position.set(
        state.camera.position.x,
        state.camera.position.y,
        state.camera.position.z
      );
    }
  }, [state.camera.position]);

  // Update camera zoom
  useEffect(() => {
    if (cameraRef.current) {
      cameraRef.current.zoom = state.camera.zoom;
      cameraRef.current.updateProjectionMatrix();
    }
  }, [state.camera.zoom]);

  // Update Earth visibility
  useEffect(() => {
    if (earthRef.current) {
      earthRef.current.visible = state.earth.visible;
    }
  }, [state.earth.visible]);

  // Update wireframe mode
  useEffect(() => {
    if (earthRef.current && earthRef.current.material.wireframe !== undefined) {
      earthRef.current.material.wireframe = state.earth.wireframe;
    }
  }, [state.earth.wireframe]);

  return {
    scene: sceneRef.current,
    renderer: rendererRef.current,
    camera: cameraRef.current,
    earth: earthRef.current,
    isInitialized,
  };
}
